import{_ as e,o,c as d,a3 as a}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/keyboard.md","filePath":"en/reference/keyboard.md"}'),r={name:"en/reference/keyboard.md"};function n(i,t,c,l,s,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/reference/keyboard.md for this page in Markdown format</div><h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Kimi Code CLI&#39;s TUI interactive mode supports a set of keyboard shortcuts. The shortcuts are organized into five groups by usage context: general input, mode switching, during streaming, tool output control, the approval panel, and popup navigation. Type <code>/help</code> in the TUI at any time to open the built-in shortcut reference.</p><h2 id="general-shortcuts" tabindex="-1">General Shortcuts <a class="header-anchor" href="#general-shortcuts" aria-label="Permalink to &quot;General Shortcuts&quot;">​</a></h2><p>The following keys are always available in the input box:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Submit the current input</td></tr><tr><td><code>Shift-Enter</code> / <code>Ctrl-J</code></td><td>Insert a newline in the input</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>Browse input history</td></tr><tr><td><code>Esc</code></td><td>Close a popup / cancel completion / interrupt streaming output or context compaction</td></tr><tr><td><code>Ctrl-C</code></td><td>Interrupt the current streaming output, or clear the input box</td></tr><tr><td><code>Ctrl-D</code></td><td>Exit Kimi Code CLI when the input box is empty</td></tr><tr><td><code>Ctrl-T</code></td><td>Expand or collapse the todo list when it is truncated</td></tr></tbody></table><p>Pressing <code>Ctrl-C</code> <strong>during streaming</strong> cancels immediately — no second confirmation needed.</p><p><strong>Exiting the program</strong> (pressing <code>Ctrl-C</code> with an empty input box, or pressing <code>Ctrl-D</code>) uses a double-press confirmation mechanism: after the first press, a prompt appears in the status bar; a second press of the same key actually exits. Pressing any other key in between clears the confirmation state.</p><h2 id="mode-switching" tabindex="-1">Mode Switching <a class="header-anchor" href="#mode-switching" aria-label="Permalink to &quot;Mode Switching&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Shift-Tab</code></td><td>Toggle Plan mode</td></tr><tr><td><code>!</code></td><td>Enter shell mode (in an empty input box)</td></tr></tbody></table><p>Press <code>Shift-Tab</code> to enable or disable Plan mode. When enabled, the Agent prioritizes read-only tools for research and planning and can write to the current plan file; <code>Bash</code> is subject to the current permission mode and regular rules, without any additional separate approval triggered by Plan mode. Simply toggling does not create an empty plan file. Press <code>Shift-Tab</code> again to exit Plan mode.</p><p>Type <code>!</code> in an empty input box to enter shell mode and run terminal commands directly; while a command is running, press <code>Ctrl+B</code> to move it to a background task. See <a href="./../guides/interaction.html#shell-mode">Interaction and input</a>.</p><h2 id="input-editing" tabindex="-1">Input &amp; Editing <a class="header-anchor" href="#input-editing" aria-label="Permalink to &quot;Input &amp; Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Ctrl-G</code></td><td>Edit the current input in an external editor</td></tr><tr><td><code>Ctrl-V</code></td><td>Paste an image or video from the clipboard (Unix / macOS)</td></tr><tr><td><code>Alt-V</code></td><td>Paste an image or video from the clipboard (Windows)</td></tr><tr><td><code>Ctrl--</code></td><td>Undo</td></tr><tr><td><code>Esc</code> <code>Esc</code></td><td>Open the undo selector (double-press while idle)</td></tr></tbody></table><p>Pressing <code>Ctrl-G</code> opens an external editor, selected according to the following priority:</p><ol><li>The editor configured via the <code>/editor</code> command</li><li>The <code>$VISUAL</code> environment variable</li><li>The <code>$EDITOR</code> environment variable</li></ol><p>After saving and exiting, the edited content replaces the input box; exiting without saving leaves the input unchanged.</p><p>When pasting an image or video, a placeholder is shown in the input box — the actual media data is sent to the model when the message is submitted. The system clipboard is read first; on Linux, Wayland and X11 are tried; on WSL, PowerShell is also used as a fallback to read the Windows clipboard.</p><h2 id="during-streaming" tabindex="-1">During Streaming <a class="header-anchor" href="#during-streaming" aria-label="Permalink to &quot;During Streaming&quot;">​</a></h2><p>While streaming output is active, the input box can still receive input and supports the following additional operations:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Ctrl-S</code></td><td>Steer: inject the current input directly into the running turn</td></tr><tr><td><code>Esc</code></td><td>Interrupt the current streaming output</td></tr><tr><td><code>Ctrl-C</code></td><td>Interrupt the current streaming output</td></tr></tbody></table><p>Pressing <code>Ctrl-S</code> causes the model to see your message at the next interruptible point, without waiting for the current turn to finish.</p><h2 id="tool-output" tabindex="-1">Tool Output <a class="header-anchor" href="#tool-output" aria-label="Permalink to &quot;Tool Output&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>Ctrl-O</code></td><td>Expand or collapse tool output and compaction summaries</td></tr></tbody></table><p>When collapsed tool call results exist in the history, press <code>Ctrl-O</code> to toggle between collapsed and expanded views. After compaction, the same shortcut shows or hides the compaction summary in the compaction block.</p><h2 id="approval-panel" tabindex="-1">Approval Panel <a class="header-anchor" href="#approval-panel" aria-label="Permalink to &quot;Approval Panel&quot;">​</a></h2><p>When the Agent initiates a tool call that requires confirmation, the TUI displays an approval panel. For the full approval workflow, see <a href="./../guides/interaction.html#approval-flow">Interaction &amp; Input</a>. The available keys inside the panel are:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Move the cursor between candidate options</td></tr><tr><td><code>Enter</code></td><td>Confirm the currently selected option</td></tr><tr><td><code>1</code> ~ <code>9</code></td><td>Directly select the option at the corresponding index</td></tr><tr><td><code>Esc</code> / <code>Ctrl-C</code> / <code>Ctrl-D</code></td><td>Reject the current request</td></tr><tr><td><code>Ctrl-E</code></td><td>Expand or collapse the full content when the panel contains a diff or file preview</td></tr><tr><td><code>Ctrl-O</code></td><td>Toggle the collapsed state of other tool output</td></tr></tbody></table><p>Options that require feedback (such as &quot;Reject&quot; or &quot;Revise&quot;) switch to a feedback input state after confirmation: type the feedback text and press <code>Enter</code> to submit; press <code>Esc</code> to exit feedback input and return to the candidate list.</p><h2 id="popup-mode" tabindex="-1">Popup Mode <a class="header-anchor" href="#popup-mode" aria-label="Permalink to &quot;Popup Mode&quot;">​</a></h2><p>After opening the help panel with <code>/help</code>, use the following keys to navigate and close it:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Scroll one line at a time</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>Scroll 10 lines at a time</td></tr><tr><td><code>Esc</code> / <code>Enter</code> / <code>q</code> / <code>Q</code></td><td>Close the panel</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./slash-commands.html">Slash Commands</a> — Quick reference for built-in TUI control commands</li><li><a href="./kimi-command.html"><code>kimi</code> Command</a> — Complete reference for startup flags and subcommands</li></ul>',34)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
